L52: function sh(cmd, args, opts = {}) {
L53:   const { input, ...rest } = opts;
L54:   const out = execFileSync(cmd, args, {
L55:     stdio: ["pipe", "pipe", "pipe"],
L56:     ...rest,
L57:     ...(input !== undefined ? { input } : {}),
L58:   });
L59:   return out === null ? "" : out.toString().trim();
L60: }
