L62: function asarHeaderHash(asarPath) {
L63:   const fd = fs.openSync(asarPath, "r");
L64:   const lenBuf = Buffer.alloc(4);
L65:   fs.readSync(fd, lenBuf, 0, 4, 12);
L66:   const jsonLen = lenBuf.readUInt32LE(0);
L67:   const header = Buffer.alloc(jsonLen);
L68:   fs.readSync(fd, header, 0, jsonLen, 16);
L69:   fs.closeSync(fd);
L70:   return sh("python3", ["-c", "import hashlib,sys;print(hashlib.sha256(sys.stdin.buffer.read()).hexdigest())"], { input: header });
L71: }
L72: 
L73: function stampIntegrity() {
L74:   const hash = asarHeaderHash(ASAR);
L75:   const stamped = sh("python3", [
L76:     "-c",
L77:     `
L78: import plistlib, sys
L79: plist_path, new_hash = sys.argv[1], sys.argv[2]
L80: with open(plist_path, "rb") as f:
L81:     plist = plistlib.load(f)
L82: plist["ElectronAsarIntegrity"]["Resources/app.asar"]["hash"] = new_hash
L83: with open(plist_path, "wb") as f:
L84:     plistlib.dump(plist, f, fmt=plistlib.FMT_BINARY)
L85: print("ok")
L86: `,
L87:     INFO_PLIST,
L88:     hash,
L89:   ]);
L90:   if (stamped !== "ok") throw new Error("plist stamping failed");
L91:   return hash;
L92: }
L93: 
L94: function resign() {
L95:   // Stable identity (matches the other patchers): ad-hoc breaks keychain ACLs.
L96:   sh("codesign", ["--force", "--deep", "--sign", process.env.OC_SIGN_IDENTITY || "OpenCode Local Notifier", APP]);
L97:   sh("codesign", ["--verify", "--deep", APP]);
L98:   console.log("codesign: re-signed with stable identity + verified OK");

